prompts.user:
/ [셋업] POS별 문항 풀에서 랜덤 인덱스(*_IDX) 추출
@SET(N_IDX, "@INDEX("@N_SEN@", "@N_SEN[.]@")@", SELF)@
@SET(V_IDX, "@INDEX("@V_SEN@", "@V_SEN[.]@")@", SELF)@
@SET(ADJ_IDX, "@INDEX("@ADJ_SEN@", "@ADJ_SEN[.]@")@", SELF)@
@SET(OTH_IDX, "@INDEX("@OTH_SEN@", "@OTH_SEN[.]@")@", SELF)@

// [셋업] 추출한 문항·정답(·보기)을 JSON_test_config에 기록
@UPJ(JSON_test_config.Noun[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 주어진 글자로 시작하는 밑줄에 들어갈 말을 채우시오.<br>@N_SEN[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].answer, "@N_ANS[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].polysemy, "@N_POLY[@N_IDX@]@")@
@UPJ(JSON_test_config.Noun[@R_i@].definition, "@N_DEF[@N_IDX@]@")@


@UPJ(JSON_test_config.Verb[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 주어진 글자로 시작하는 밑줄에 들어갈 말을 채우시오.<br>@V_SEN[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].answer, "@V_ANS[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].polysemy, "@V_POLY[@V_IDX@]@")@
@UPJ(JSON_test_config.Verb[@R_i@].definition, "@V_DEF[@V_IDX@]@")@

@UPJ(JSON_test_config.Adjective[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 주어진 글자로 시작하는 밑줄에 들어갈 말을 채우시오.<br>@ADJ_SEN[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].answer, "@ADJ_ANS[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].polysemy, "@ADJ_POLY[@ADJ_IDX@]@")@
@UPJ(JSON_test_config.Adjective[@R_i@].definition, "@ADJ_DEF[@ADJ_IDX@]@")@

@UPJ(JSON_test_config.others[@R_i@].problem, "@EVAL(@R_i@)@. 아래 문장 속 주어진 글자로 시작하는 밑줄에 들어갈 말을 채우시오.<br>@OTH_SEN[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].answer, "@OTH_ANS[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].polysemy, "@OTH_POLY[@OTH_IDX@]@")@
@UPJ(JSON_test_config.others[@R_i@].definition, "@OTH_DEF[@OTH_IDX@]@")@

// [채점] 학생 응답 정오 판정 후 점수·correctness 기록 (EXACT: 정확 일치)

1. Noun
T/F boolean: @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@

Current Score: @JSON_test_config.Result[1].Noun@

Enumerated: @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@

update:
@UPJ(JSON_test_config.Result[1].Noun, @EVAL("@JSON_test_config.Result[1].Noun@ + @MAP("@TEXT(P_N@R_i@)@", "@JSON_test_config.Noun[@R_i@].answer@", "1|0",EXACT)@")@)@
@UPJ(JSON_test_config.Noun[@R_i@].Student_answer, "@TEXT(P_N@R_i@)@")@
